begin
-- Enrich the seven existing Meta products; preserve their Meta IDs, links and descriptions.
update public."Product" as product set
  store_id=item.store_id, category=item.category, short_description=item.short_description,
  images=item.images, store_sort_order=item.store_sort_order, store_active=true
from jsonb_to_recordset(catalog_data) as item(store_id text, category text, name text, short_description text, images jsonb, variants jsonb, store_sort_order integer)
where lower(product.name)=lower(item.name) and product.catalog_id='1515875913870520';

-- Add only products missing from the existing Product table.
insert into public."Product" (name, retailer_id, catalog_id, description, store_id, category, short_description, images, store_sort_order, store_active)
select item.name, item.store_id, 'madikar-store', item.short_description, item.store_id,
  item.category, item.short_description, item.images, item.store_sort_order, true
from jsonb_to_recordset(catalog_data) as item(store_id text, category text, name text, short_description text, images jsonb, variants jsonb, store_sort_order integer)
where not exists (select 1 from public."Product" p where lower(p.name)=lower(item.name));

-- Pack sizes are distinct variants linked to those same Product records.
insert into public."ProductVariant" (product_id, position, size, price)
select product.id, (variant.ordinality-1)::integer, variant.value->>'size', (variant.value->>'price')::numeric
from jsonb_to_recordset(catalog_data) as item(store_id text, category text, name text, short_description text, images jsonb, variants jsonb, store_sort_order integer)
join public."Product" product on product.store_id=item.store_id
cross join lateral jsonb_array_elements(item.variants) with ordinality as variant(value, ordinality)
on conflict (product_id, position) do nothing;
end;
$seed_block$;
